answer.text:
// Run first: the caller takes these 10 rows (id, title, distance) as the answer's base and collects the ids.
query nearest_docs($q: Vector(3)) {
    match { $d: Doc }
    return { $d.id, $d.title, nearest($d.embedding, $q) as distance }
    order { nearest($d.embedding, $q) }
    limit 10
}

// Run second, passing the ids from the first query as $ids: the caller merges these counts into the first query's rows by id, and sets cites = 0 for any id that does not appear here (documents citing nothing produce no row).
query cite_counts($ids: [String]) {
    match {
        $d: Doc
        $d.id in $ids
        $d cites $c
    }
    return { $d.id, count($c) as cites }
}

