answer.text:
// Run first. People who know at least one person, with their degree, most connected first.
// Grouped by handle (the key) so two people sharing a name are not merged; the caller uses name and degree.
query people_with_friends() {
    match {
        $p: Person
        $p knows $f
    }
    return {
        $p.handle
        $p.name
        count($f) as degree
    }
    order { degree desc }
}

// Run second. People who know nobody. The caller gives each of these degree 0
// and appends them after the rows from the first query, which are already sorted by degree.
query people_with_no_friends() {
    match {
        $p: Person
        not { $p knows $_ }
    }
    return { $p.handle, $p.name }
}

