query colleagues($of: String) {
    match {
        $p: Person { handle: $of }
        $p worksAt $c
        $q worksAt $c
        $q.handle != $of
    }
    return { $q.handle, $q.name }
}

// GQ has no way to call one query from another, so this query inlines the colleagues pattern twice.
query colleagues_of_colleagues($of: String) {
    match {
        $p: Person { handle: $of }
        $p worksAt $c1
        $q worksAt $c1
        $q.handle != $of
        $q worksAt $c2
        $r worksAt $c2
        $r.handle != $q.handle
    }
    return distinct { $r.name }
}

