answer.text:
// GQ cannot express "any number of hops": unbounded traversal is rejected ({1,} is T15).
// The caller runs this with a finite bound (here 10) and collects the names.
// If the result is non-empty, the caller re-runs it with {1,20}, {1,40}, ... and stops
// once two consecutive runs return the same set of names. Hops are shortest-path
// distances, so an unchanged set means the closure is complete.
query reachable_by_knows($from: String) {
    match {
        $p: Person { handle: $from }
        $p knows{1,10} $f
    }
    return distinct { $f.name }
}

