// GQ edition 2 has no arithmetic in `set` and cannot read a value into a mutation,
// so `age + 1` cannot be expressed with only `$h`. The caller must pass the
// already-incremented age as `$new_age`.
query birthday($h: String, $new_age: I32) {
    update Person set { age: $new_age } where handle = $h
}

