answer.text:
// GQ edition 2 cannot express this as one query. A mutation has only
// insert/update/delete with a `where`, and no `order`, `limit` or `nearest`.
// A read query has no write step. This is the read half: it returns the ids of
// the 20 nearest documents. A second mutation would then set the tags, e.g.
//   update Doc set { tags: ["near"] } where id in $ids
query nearest_docs($q: Vector(3)) {
    match { $d: Doc }
    return { $d.id }
    order { nearest($d.embedding, $q) }
    limit 20
}

