answer.text:
// Run first: lists every source the channel watches, including those with no touchpoints.
query watched_sources($channel: String) {
    match {
        $c: Channel { slug: $channel }
        $c channelWatchesSource $s
    }
    return { $s.slug }
}

// Run second: touchpoint counts per watched source. The caller merges these with the first result and treats any source missing here as touchpoints = 0.
query watched_source_touchpoints($channel: String) {
    match {
        $c: Channel { slug: $channel }
        $c channelWatchesSource $s
        $t touchpointOnSource $s
    }
    return { $s.slug, count($t) as touchpoints }
    order { touchpoints desc }
}

