answer.text:
// GQ has no nested aggregation, so it cannot average or take the max of per-identity counts in one query.
// The caller takes the returned rows (one per identity that has at least one touchpoint, as `n`),
// computes mean = sum(n) / number of rows, and largest = max(n), which is the first row because of the ordering.
query touchpoints_per_identity() {
    match {
        $i: ExternalID
        $t: Touchpoint
        $t touchpointByIdentity $i
    }
    return {
        $i.slug,
        count($t) as n
    }
    order { n desc }
}

