// Run first. Rank 1..3 is the order of the rows returned.
query nearest_docs($v: Vector(2)) {
    match { $d: Doc }
    return { $d.slug }
    order { nearest($d.embedding, $v) }
    limit 3
}

// Run second. Rank is the row order, best first.
// The caller computes reciprocal rank fusion over both lists: score(slug) = sum of 1/(60 + rank) over each list that contains it, with rank starting at 1.
// It then sorts by score descending and keeps the top 3 slugs, best first.
query bm25_docs($q: String) {
    match { $d: Doc }
    return { $d.slug }
    order { bm25($d.body, $q) }
}

