// (handle is returned only so people who share a name are not merged into one group.)
query people_with_degree() {
    match {
        $p: Person
        $p knows $f
    }
    return {
        $p.handle
        $p.name
        count($f) as degree
    }
    order { degree desc }
}

// Run second. People who know nobody. The caller appends these rows
// after the first query's rows, with degree = 0 for each (the traversal
// above is an inner match, so these people cannot appear there).
query people_without_acquaintances() {
    match {
        $p: Person
        not { $p knows $_ }
    }
    return { $p.handle, $p.name }
}

