// Run first. The caller keeps the rows where n >= min_docs.
// GQ cannot compare an aggregate to a per-row property.
query collection_doc_counts() {
    match {
        $c: Collection
        $d in $c
    }
    return { $c.slug, $c.min_docs, count($d) as n }
}

// Run second. The caller adds these slugs to the result of the first query.
// Collections with no documents are missing from the join above, but they
// qualify when min_docs <= 0, and a collection with documents is simply deduplicated.
query collections_needing_no_docs() {
    match {
        $c: Collection
        $c.min_docs <= 0
    }
    return { $c.slug }
}

