// Run first: the 10 documents nearest to $q among all documents.
// The caller keeps the ids from this result and passes them to the next query.
query nearest_docs($q: Vector(3)) {
    match { $d: Doc }
    return { $d.id, $d.title }
    order { nearest($d.embedding, $q) }
    limit 10
}

// Run second, with $ids set to the ids returned by nearest_docs.
// The rows returned are the titles of those 10 documents that belong to collection $coll.
query nearest_in_collection($coll: String, $ids: [String]) {
    match {
        $c: Collection { slug: $coll }
        $d: Doc
        $d.id in $ids
        $d in $c
    }
    return { $d.id, $d.title }
}

