// Unbounded traversal is rejected (`{1,}` is T15), so this cannot be one query.
// The caller runs this query in a loop, starting with $handles = [$from].
// Each round it adds the returned handles it hasn't seen to a visited set and
// passes the new ones as the next $handles. It stops when a round returns no
// new handles. Finally it takes the distinct `name` values across all rounds'
// results. That set is everyone reachable from $from by one or more `knows` edges.
query knows_step($handles: [String]) {
    match {
        $p: Person
        $p.handle in $handles
        $p knows $f
    }
    return distinct { $f.handle, $f.name }
}

