// Run `colleagues_of_colleagues` on its own: it repeats the colleagues pattern and applies it once more,
// so the result is the distinct names of the colleagues of $of's colleagues.
query colleagues_of_colleagues($of: String) {
    match {
        $p: Person { handle: $of }
        $p worksAt $c
        $q worksAt $c
        $q.handle != $of
        $q worksAt $d
        $r worksAt $d
        $r.handle != $q.handle
    }
    return distinct { $r.name }
}

