answer.text:
// GQ cannot express "any number of hops": traversal bounds must be finite, and `{1,}` is rejected.
// The caller runs this query repeatedly as a breadth-first search:
//   1. Start with frontier = [the original handle] and seen = {}.
//   2. Run this query once per frontier handle, passing it as $from.
//   3. Add every returned handle not already in seen to seen, and make those new handles the next frontier.
//   4. Repeat until the frontier is empty.
//   5. Collect the distinct `name` values of everything in seen. This is the answer.
//      The start person is included only if a cycle leads back to them.
query knows_neighbors($from: String) {
    match {
        $p: Person { handle: $from }
        $p knows $f
    }
    return distinct { $f.handle, $f.name }
}

