answer.text:
// Unbounded traversal is rejected ({1,} is T15), so "any number of times" can't be a single query.
// Run this first: the caller keeps the returned handles as `seen` and as the first `frontier`.
query reach_step_one($from: String) {
    match {
        $p: Person { handle: $from }
        $p knows $q
    }
    return distinct { $q.handle, $q.name }
}

// Caller loops on this: pass `$frontier` as the handles first seen in the previous round.
// Add any returned handle not already in `seen` to `seen`, and use those new handles as the next frontier.
// Stop when a round yields no new handles. The answer is the distinct names of everything in `seen`.
// Drop the start person's own name unless their handle turned up in a result (reachable through a cycle).
query reach_step($frontier: [String]) {
    match {
        $p: Person
        $p.handle in $frontier
        $p knows $q
    }
    return distinct { $q.handle, $q.name }
}

