// GQ can't aggregate over an aggregate, so one query can't return mean and largest.
// This query returns one row per identity with its touchpoint count, ordered largest first.
// The caller computes `largest` as the first row's `touchpoints`.
// The caller computes `mean` as the average of `touchpoints` across all rows.
// Identities with no touchpoints don't appear. If they should count as 0 in the mean,
// the caller must divide by the total number of ExternalID nodes instead.
query touchpoints_per_identity() {
    match {
        $t: Touchpoint
        $t touchpointByIdentity $e
    }
    return {
        $e.slug
        count($t) as touchpoints
    }
    order { touchpoints desc }
}

